// Turn the fetched emails and events into tagged data for the AI.
// Everything from an email or invite is written by someone else. It is cleaned first, then
// wrapped in tags whose name changes on every run (untrusted_email_<random>), so an email
// can't guess the tag and fake its end:
//  - every link, bare web address, IP address or mailto: becomes [link: domain[.]com], with the
//    dots broken so mail apps don't turn it back into a link. A link with a user@ part, which can
//    hide the real site, becomes [link: suspicious]. File names like report.pdf are left alone.
//  - the words untrusted_email / untrusted_event become [tag removed]
//  - < > become ‹ ›, so no text can open or close a tag
//  - { } become ( ), which the AI node would otherwise read as template fields
const settings = $('Work out the window').first().json;
const tz = $now.zoneName;   // follows the workflow's timezone setting
const SHOW = 20;           // emails shown in the brief (Find recent emails asks for one more to spot overflow)
const BODY_CAP = 1500;      // characters of each email body the AI sees
const nonce = Math.random().toString(36).slice(2, 10);
const EMAIL_TAG = `untrusted_email_${nonce}`;
const EVENT_TAG = `untrusted_event_${nonce}`;

const FILE_EXT = 'pdf|docx?|xlsx?|pptx?|csv|txt|rtf|odt|ods|png|jpe?g|gif|webp|heic|svg|mp3|wav|ics|eml';
const LABEL = '[\\p{L}\\p{N}](?:[\\p{L}\\p{N}-]*[\\p{L}\\p{N}])?';
const TLD = '(?:xn--[a-z0-9-]+|\\p{L}{2,})';
const TAIL = '[^\\s<>"\'()\\[\\]]';   // characters a link can carry after the host
const SCHEME_URL = new RegExp(`\\b(?:https?|ftp):\\/\\/([^\\s\\/?#<>"'()\\[\\]]+)${TAIL}*`, 'giu');
const WWW_URL = new RegExp(`\\bwww\\.([^\\s\\/?#<>"'()\\[\\]]+)${TAIL}*`, 'giu');
const OTHER_SCHEME = new RegExp(`\\b(?:mailto|data|javascript|file|sms|tel|ftp):${TAIL}+`, 'giu');
const IPV4 = new RegExp(`(?<![\\p{N}.])((?:\\d{1,3}\\.){3}\\d{1,3})(?!\\.?\\p{N})(?::\\d+)?(?:[\\/?#]${TAIL}*)?`, 'gu');
const BARE_DOMAIN = new RegExp(`(?<![@\\p{L}\\p{N}._\\/-])((?:${LABEL}\\.)+(?!(?:${FILE_EXT})(?![\\p{L}\\p{N}-]))${TLD})(?!\\.?[\\p{L}\\p{N}@_-])(?::\\d+)?(?:[\\/?#]${TAIL}*)?`, 'giu');

const defang = h => String(h || '').toLowerCase().replace(/:\d+$/, '').replace(/\.+$/, '').replace(/\./g, '[.]');
// Sentence punctuation after a link (a comma, a full stop) stays outside the label.
const hostLink = (m, host) => {
  const end = (m.match(/[.,;:!?]+$/) || [''])[0];
  const h = host.replace(/[.,;:!?]+$/, '');
  return (h.includes('@') ? '[link: suspicious]' : `[link: ${defang(h)}]`) + end;
};
const clean = s => String(s == null ? '' : s)
  .replace(SCHEME_URL, hostLink)
  .replace(WWW_URL, hostLink)
  .replace(OTHER_SCHEME, '[link]')
  .replace(IPV4, (m, ip) => `[link: ${defang(ip)}]`)
  .replace(BARE_DOMAIN, (m, host) => `[link: ${defang(host)}]`)
  .replace(/untrusted[\s_-]*(?:email|event)\w*/gi, '[tag removed]')
  .replace(/</g, '‹').replace(/>/g, '›')
  .replace(/\{/g, '(').replace(/\}/g, ')');

// Gmail sends bodies base64url-encoded. Attachments arrive as ids only, never their data.
const fromB64 = d => {
  const s = String(d || '').replace(/-/g, '+').replace(/_/g, '/');
  if (typeof Buffer !== 'undefined') return Buffer.from(s, 'base64').toString('utf8');
  return new TextDecoder().decode(Uint8Array.from(atob(s), c => c.charCodeAt(0)));
};
const findPart = (p, type) => {
  if (!p) return '';
  if (p.mimeType === type && !p.filename && p.body && p.body.data) return fromB64(p.body.data);
  for (const c of p.parts || []) {
    const t = findPart(c, type);
    if (t) return t;
  }
  return '';
};
// HTML-only emails: keep each link's real address next to its text, so it gets cleaned like any other.
const htmlToText = h => h
  .replace(/<(style|script|head)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<blockquote[\s\S]*?<\/blockquote>/gi, ' ')
  .replace(/<a\b[^>]*?href\s*=\s*["']?([^"'\s>]+)[^>]*>([\s\S]*?)<\/a>/gi, '$2 $1')
  .replace(/<br\s*\/?>|<\/(?:p|div|li|tr|h\d)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/&amp;/gi, '&');
const header = (m, name) => {
  const h = ((m.payload && m.payload.headers) || []).find(x => String(x.name).toLowerCase() === name);
  return h ? h.value : '';
};
// Drop the quoted history under a reply so the cap is spent on the new message.
const newPart = t => String(t || '')
  .split(/\r?\n/).filter(l => !/^\s*>/.test(l)).join('\n')
  .split(/\n\s*On .{0,200}wrote:\s*\n/)[0];

const fetched = $('Recent emails').isExecuted ? $('Recent emails').all().map(i => i.json) : [];
const all = fetched.filter(m => m && m.id && m.payload);
const emails = all.slice(0, SHOW).map((m, n) => {
  const text = findPart(m.payload, 'text/plain') || htmlToText(findPart(m.payload, 'text/html')) || m.snippet || '';
  const body = newPart(text).replace(/\s+/g, ' ').trim().slice(0, BODY_CAP);
  return `<${EMAIL_TAG} id="${n + 1}">\nFrom: ${clean(header(m, 'from'))}\nSubject: ${clean(header(m, 'subject') || '(no subject)')}\nBody: ${clean(body)}\n</${EMAIL_TAG}>`;
});

const events = $("Today's calendar").all()
  .map(i => i.json)
  .filter(e => e && (e.id || e.summary))
  .map((e, n) => {
    const start = e.start && (e.start.dateTime || e.start.date);
    const end = e.end && (e.end.dateTime || e.end.date);
    const time = e.start && e.start.dateTime
      ? `${DateTime.fromISO(start).setZone(tz).toFormat('HH:mm')}–${DateTime.fromISO(end).setZone(tz).toFormat('HH:mm')}`
      : 'All day';
    const who = (e.attendees || []).map(p => p.displayName || p.email).filter(Boolean).slice(0, 8).join(', ');
    return `<${EVENT_TAG} id="${n + 1}">\nTime: ${time}\nTitle: ${clean(e.summary || '(no title)')}${who ? '\nWith: ' + clean(who) : ''}${e.location ? '\nWhere: ' + clean(e.location) : ''}\n</${EVENT_TAG}>`;
  });

return [{ json: {
  name: settings.your_name,
  email: settings.to,
  date: $now.toFormat('cccc d LLLL yyyy'),
  email_tag: EMAIL_TAG,
  event_tag: EVENT_TAG,
  email_count: emails.length,
  emails_truncated: all.length > SHOW,
  event_count: events.length,
  emails_text: emails.length ? emails.join('\n\n') : 'No new emails.',
  events_text: events.length ? events.join('\n\n') : 'No meetings today.',
} }];

